-- Migration: Year 3 - Small Bowel, Colon, Rectum & Anus MCQ Bank (COMPLETE: 1-350)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'colorectal-anal-surgery' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Small Bowel Anatomy, Physiology, and Obstruction
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the primary site for the absorption of Iron in the small intestine?', '["Duodenum", "Jejunum", "Ileum", "Colon"]', 0, 'Most iron absorption occurs in the duodenum. (Schwartz''s Ch. 28)'),
    (v_topic_id, '2: Vitamin B12 and Bile Salts are primarily absorbed in the:', '["Duodenum", "Proximal Jejunum", "Terminal Ileum", "Cecum"]', 2, 'Requires Intrinsic Factor (for B12) and the enterohepatic circulation. (de Virgilio Ch. 21)'),
    (v_topic_id, '3: The most common cause of Small Bowel Obstruction (SBO) in the United States is:', '["Hernia", "Post-operative adhesions", "Malignancy", "Crohn''s disease"]', 1, 'Scars from previous surgery are the #1 cause. (Mont Reid Ch. 8)'),
    (v_topic_id, '4: On abdominal X-ray, SBO is characterized by dilated loops of small bowel and:', '["Air-fluid levels", "Air in the rectum", "Free air under the diaphragm", "None"]', 0, 'Step-ladder pattern of air-fluid levels is classic. (Schwartz''s Ch. 28)'),
    (v_topic_id, '5: "Gallstone Ileus" is caused by a large gallstone eroding through the gallbladder into the duodenum and obstructing the:', '["Pylorus", "Treitz", "Ileocecal valve", "None"]', 2, 'The Narrowest part of the small bowel. (de Virgilio Ch. 21)'),
    (v_topic_id, '6: "Rigler''s Triad" for Gallstone Ileus includes: Pneumobilia, SBO, and ____.', '["Fever", "Ectopic gallstone (usually in RLQ)", "Jaundice", "None"]', 1, 'Classic radiographic findings. (Mont Reid Ch. 8)'),
    (v_topic_id, '7: What is the first-line management for a non-strangulated SBO?', '["Immediate surgery", "NG tube decompression and IV fluid resuscitation", "Barium enema", "None"]', 1, '"Drip and Suck" - often resolves spontaneously. (Schwartz''s Ch. 28)'),
    (v_topic_id, '8: A "Strangulated" SBO is suggested by which clinical finding?', '["Fever, leukocytosis, and localized tenderness", "Increased gas", "High-pitched bowel sounds", "None"]', 0, 'Indicates ischemia; requires emergent surgery. (de Virgilio Ch. 21)'),
    (v_topic_id, '9: "Small Bowel Carcinoid" tumors most commonly occur in the ____ and can produce "Carcinoid Syndrome" if they metastasize to the ____.', '["Duodenum/Spleen", "Ileum/Liver", "Jejunum/Lung", "None"]', 1, 'Liver metastasis bypasses first-pass metabolism of serotonin. (Mont Reid Ch. 8)'),
    (v_topic_id, '10: "Meckel''s Diverticulum" is a "true" diverticulum caused by the persistence of the ____.', '["Urachus", "Vitelline (Omphalomesenteric) duct", "Aorta", "None"]', 1, 'Rule of 2s: 2 inches long, 2 feet from ileocecal valve, 2% of population. (Schwartz''s Ch. 28)'),

    -- SECTION 2: Crohn's Disease and Mesenteric Ischemia
    (v_topic_id, '11: "Crohn''s Disease" is characterized by transmural inflammation and which classic endoscopic finding?', '["Continuous lesions", "Skip lesions and Cobblestoning", "Pseudopolyps", "None"]', 1, 'Can affect any part of the GI tract from mouth to anus. (de Virgilio Ch. 15)'),
    (v_topic_id, '12: Which surgical procedure is used to treat Crohn''s strictures while preserving bowel length?', '["Resection", "Strictureplasty (e.g., Heineke-Mikulicz)", "Bypass", "None"]', 1, 'Useful in patients with multiple short strictures. (Schwartz''s Ch. 28)'),
    (v_topic_id, '13: "Creeping Fat" is a pathognomonic surgical finding for:', '["Ulcerative Colitis", "Crohn''s Disease", "Cancer", "None"]', 1, 'Mesenteric fat wrapping around the bowel wall. (Mont Reid Ch. 8)'),
    (v_topic_id, '14: "Acute Mesenteric Ischemia" is most commonly caused by an embolus originating from the:', '["Liver", "Heart (Atrial Fibrillation)", "Veins", "None"]', 1, 'The SMA is the most common site of embolization. (de Virgilio Ch. 22)'),
    (v_topic_id, '15: The classic presentation of Acute Mesenteric Ischemia is "Pain out of ____ to the physical exam."', '["Proportion", "Control", "Sight", "None"]', 0, 'Severe pain with a relatively benign-looking abdomen initially. (Schwartz''s Ch. 23)'),
    (v_topic_id, '16: "Chronic Mesenteric Ischemia" (Intestinal Angina) presents with weight loss and ____.', '["Diarrhea", "Postprandial pain (fear of eating)", "Jaundice", "None"]', 1, 'Due to atherosclerotic disease of the celiac and/or SMA. (Mont Reid Ch. 8)'),
    (v_topic_id, '17: "Ischemic Colitis" most commonly occurs at the "Watershed Areas," including the "Splenic Flexure" (Griffith''s Point) and the ____.', '["Cecum", "Rectosigmoid junction (Sudek''s point)", "Hepatic flexure", "None"]', 1, 'Areas of precarious blood supply. (de Virgilio Ch. 16)'),
    (v_topic_id, '18: "SMA Syndrome" (Wilkie''s Syndrome) is an obstruction of the 3rd part of the duodenum caused by compression between the SMA and the:', '["Spine", "Aorta", "Liver", "None"]', 1, 'Common after rapid weight loss (loss of fat pad). (Schwartz''s Ch. 28)'),
    (v_topic_id, '19: "Intussusception" in adults is most commonly caused by:', '["Idiopathic", "A lead point (often a tumor)", "Virus", "None"]', 1, 'Unlike children, adults with intussusception usually need surgery. (Mont Reid Ch. 1)'),
    (v_topic_id, '20: What is the preferred diagnostic test for mesenteric ischemia?', '["Endoscopy", "CT Angiogram (CTA)", "Ultrasound", "None"]', 1, 'Allows visualization of vessels and bowel wall. (de Virgilio Ch. 22)'),

    -- SECTION 3: Appendicitis and Diverticulitis
    (v_topic_id, '21: "Appendicitis" usually begins with vague periumbilical pain that later localizes to the RLQ (McBurney''s point). This shift is due to:', '["Nerve death", "Irritation of the parietal peritoneum", "Bowel movement", "None"]', 1, 'Visceral pain (T10) followed by somatic pain. (Schwartz''s Ch. 30)'),
    (v_topic_id, '22: "Rovsing''s Sign" is RLQ pain elicited by:', '["Pressure on the RLQ", "Pressure on the LLQ", "Coughing", "None"]', 1, 'Indicates peritoneal irritation. (de Virgilio Ch. 13)'),
    (v_topic_id, '23: The most common bug in appendicitis is ____, but the most common "pathogen" associated with rupture is ____.', '["Staph; Strep", "Bacteroides fragilis; E. coli", "E. coli; Bacteroides fragilis", "None"]', 2, 'Gram-negatives and anaerobes. (Mont Reid Ch. 8)'),
    (v_topic_id, '24: A "Retrocecal" appendix may present with a positive ____ sign.', '["Rovsing", "Psoas", "Obturator", "None"]', 1, 'Pain on passive extension of the right hip. (Schwartz''s Ch. 30)'),
    (v_topic_id, '25: In a pregnant patient with appendicitis, the appendix is often shifted ____.', '["Down", "Up and Lateral (toward the RUQ)", "Medial", "None"]', 1, 'Due to the enlarging uterus. (de Virgilio Ch. 13)'),
    (v_topic_id, '26: "Diverticulosis" (pseudodiverticula) most commonly involves which part of the colon?', '["Cecum", "Sigmoid colon", "Transverse colon", "None"]', 1, 'Highest pressure zone. (Mont Reid Ch. 8)'),
    (v_topic_id, '27: "Diverticulitis" is an inflammation/infection of a diverticulum. What is the "gold standard" diagnostic test?', '["Colonoscopy", "CT Abdomen/Pelvis with IV contrast", "Barium enema", "None"]', 1, 'Colonoscopy is CONTRAINDICATED in acute diverticulitis due to risk of perforation. (Schwartz''s Ch. 29)'),
    (v_topic_id, '28: "Hinchey Classification" Stage I refers to:', '["Distant abscess", "Pericolic abscess", "Purulent peritonitis", "Fecal peritonitis"]', 1, 'Localized infection. (de Virgilio Ch. 16)'),
    (v_topic_id, '29: "Hinchey Stage IV" (Fecal peritonitis) requires emergent surgery, usually a:', '["Right hemicolectomy", "Hartmann''s Procedure (Sigmoid resection, end colostomy, and rectal stump)", "Primary anastomosis", "None"]', 1, 'Standard for gross contamination. (Mont Reid Ch. 8)'),
    (v_topic_id, '30: What is the most common fistula associated with diverticulitis?', '["Colovaginal", "Colovesical (to the bladder)", "Coloenteric", "None"]', 1, 'Presents with pneumaturia (air in urine) and fecaluria. (Schwartz''s Ch. 29)'),

    -- SECTION 4: Ulcerative Colitis (UC) and Colorectal Cancer
    (v_topic_id, '31: "Ulcerative Colitis" involves the mucosa/submucosa and begins in the ____, spreading continuously.', '["Terminal Ileum", "Rectum", "Cecum", "None"]', 1, '"Lead pipe" appearance on chronic imaging. (de Virgilio Ch. 16)'),
    (v_topic_id, '32: "Toxic Megacolon" is a life-threatening complication of UC (and C. diff) characterized by colonic dilation > ____ cm.', '["2", "6", "10", "None"]', 1, 'Requires aggressive medical therapy or total colectomy. (Schwartz''s Ch. 29)'),
    (v_topic_id, '33: The surgical "cure" for UC (when medical therapy fails or dysplasia is found) is:', '["Segmental resection", "Total Proctocolectomy with Ileal Pouch-Anal Anastomosis (IPAA/J-pouch)", "Bypass", "None"]', 1, 'Removes all at-risk mucosa while preserving continence. (Mont Reid Ch. 8)'),
    (v_topic_id, '34: "Colorectal Cancer" (CRC) screening for average-risk individuals should now begin at age ____.', '["40", "45", "50", "60"]', 1, 'Updated guidelines (ACS/USPSTF). (de Virgilio Ch. 16)'),
    (v_topic_id, '35: "Right-sided" colon cancers (Cecum/Ascending) are more likely to present with:', '["Obstruction", "Iron deficiency anemia (occult bleed)", "Change in stool caliber", "None"]', 1, 'The large caliber of the right colon allows tumors to grow large before obstructing. (Schwartz''s Ch. 29)'),
    (v_topic_id, '36: "Left-sided" colon cancers (Sigmoid/Descending) are more likely to present with:', '["Anemia", "Partial bowel obstruction / ''Apple core'' lesions", "Jaundice", "None"]', 1, 'Narrower lumen and more solid stool. (Mont Reid Ch. 8)'),
    (v_topic_id, '37: What is the serum marker used for "monitoring" (not screening) colorectal cancer recurrence?', '["CA-125", "CEA (Carcinoembryonic Antigen)", "PSA", "AFP"]', 1, 'Serial measurements post-op. (de Virgilio Ch. 16)'),
    (v_topic_id, '38: "FAP" (Familial Adenomatous Polyposis) is caused by a mutation in the ____ gene and carries a 100% risk of CRC.', '["p53", "APC", "KRAS", "BRAF"]', 1, 'Requires prophylactic colectomy in late teens/early 20s. (Schwartz''s Ch. 29)'),
    (v_topic_id, '39: "Lynch Syndrome" (HNPCC) is caused by mutations in ____ genes.', '["Tumor suppressor", "DNA Mismatch Repair (MMR) (e.g., MLH1, MSH2)", "Apoptosis", "None"]', 1, 'Increased risk of CRC, endometrial, and ovarian cancers. (Mont Reid Ch. 8)'),
    (v_topic_id, '40: For a "Rectal Cancer" in the lower 1/3 that invades the sphincter complex, the required surgery is:', '["LAR (Low Anterior Resection)", "APR (Abdominoperineal Resection)", "Polypectomy", "None"]', 1, 'Requires permanent end colostomy. (de Virgilio Ch. 16)'),

    -- SECTION 5: Volvulus and Anorectal Conditions
    (v_topic_id, '41: "Sigmoid Volvulus" shows which classic sign on X-ray?', '["Bird''s beak", "Coffee bean sign", "Apple core", "None"]', 1, 'Twisted, air-filled loop of sigmoid. (Schwartz''s Ch. 29)'),
    (v_topic_id, '42: What is the initial treatment for an uncomplicated Sigmoid Volvulus?', '["Surgery", "Sigmoidoscopic decompression (detorsion)", "Barium enema", "None"]', 1, 'Followed by elective resection (high recurrence). (de Virgilio Ch. 16)'),
    (v_topic_id, '43: "Cecal Volvulus" is less common and usually requires ____ because detorsion is often unsuccessful.', '["Observation", "Right hemicolectomy", "Bandage", "None"]', 1, 'Due to failure of cecal fixation. (Mont Reid Ch. 8)'),
    (v_topic_id, '44: "Internal Hemorrhoids" are ____ the dentate line and are typically ____.', '["Above; Painful", "Above; Painless (but bleed)", "Below; Painful", "None"]', 1, 'Graded I to IV based on prolapse. (Schwartz''s Ch. 31)'),
    (v_topic_id, '45: "External Hemorrhoids" are ____ the dentate line and can be very painful if ____.', '["Above; Prolapsed", "Below; Thrombosed", "Above; Bleeding", "None"]', 1, 'Covered by anoderm (pain-sensitive). (de Virgilio Ch. 16)'),
    (v_topic_id, '46: An "Anal Fissure" most commonly occurs in the ____ midline.', '["Anterior", "Posterior", "Lateral", "None"]', 1, 'If off-midline, suspect Crohn''s, TB, or HIV. (Mont Reid Ch. 8)'),
    (v_topic_id, '47: What is the definitive surgical treatment for a refractory anal fissure?', '["Fistulectomy", "LIS (Lateral Internal Sphincterotomy)", "Hemorrhoidectomy", "None"]', 1, 'Cuts the internal sphincter to reduce spasm and allow healing. (Schwartz''s Ch. 31)'),
    (v_topic_id, '48: "Goodsall''s Rule" states that fistulas with an external opening "anterior" to the transverse anal line follow a ____ path.', '["Curved", "Straight (direct)", "Circular", "None"]', 1, 'Posterior openings follow a curved path to the posterior midline. (de Virgilio Ch. 16)'),
    (v_topic_id, '49: A "Perianal Abscess" should be treated with:', '["Antibiotics alone", "Incision and Drainage (I&D)", "Hot packs", "None"]', 1, '"Don''t let the sun set on an undrained abscess." (Mont Reid Ch. 8)'),
    (v_topic_id, '50: "Pilonidal Disease" is an infection of the skin and subcutaneous tissue at or near the ____.', '["Groin", "Sacrococcygeal cleft", "Umbilicus", "None"]', 1, 'Likely due to ingrown hairs. (Schwartz''s Ch. 31)');

    -- Batch 2: 51-150 (Deep Dive Colorectal & Anal)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Small Bowel" - what is the length in a living adult?', '["1 meter", "3 to 6 meters", "10 meters", "None"]', 1, 'Length is greater in cadavers due to loss of tone. (Schwartz''s Ch. 28)'),
    (v_topic_id, '52: "Valvulae Conniventes" (Plicae Circulares) are characteristic of:', '["Stomach", "Small Bowel", "Colon", "None"]', 1, 'Circular folds that cross the entire lumen. (de Virgilio Ch. 21)'),
    (v_topic_id, '53: "Haustra" are characteristic of:', '["Small Bowel", "Colon", "Esophagus", "None"]', 1, 'Pouches that do NOT cross the entire lumen. (Mont Reid Ch. 8)'),
    (v_topic_id, '54: "Teniae Coli" are three longitudinal bands of muscle in the ____.', '["Small bowel", "Colon (ending at the rectum)", "Stomach", "None"]', 1, 'Rectum has a continuous outer longitudinal layer. (Schwartz''s Ch. 29)'),
    (v_topic_id, '55: "Ogivlie Syndrome" is an "acute colonic pseudo-obstruction" most common in:', '["Kids", "Elderly/Bedbound patients with systemic illness", "Athletes", "None"]', 1, 'Functional obstruction without a mechanical cause. (de Virgilio Ch. 16)'),
    (v_topic_id, '56: "Neostigmine" is used to treat Ogilvie Syndrome by ____.', '["Inhibiting Acetylcholine", "Increasing Acetylcholinesterase", "Stimulating parasympathetic activity (ACh-esterase inhibitor)", "None"]', 2, 'Must monitor for bradycardia. (Mont Reid Ch. 8)'),
    (v_topic_id, '57: "Rectal Prolapse" (Procidentia) is a full-thickness protrusion. Initial management for an elderly, poor-risk patient might be:', '["Altemeier (Perineal proctectomy)", "Ripstein (Abdominal pexy)", "None", "None"]', 0, 'Perineal approaches are lower risk. (Schwartz''s Ch. 29)'),
    (v_topic_id, '58: "Solitary Rectal Ulcer Syndrome" is associated with:', '["Straining and internal intussusception", "Cancer", "Infection", "None"]', 0, 'Benign but difficult to treat. (de Virgilio Ch. 16)'),
    (v_topic_id, '59: "Anal Cancer" (Squamous Cell) is most commonly treated with the "Nigro Protocol," which is:', '["Surgery", "Chemo + Radiation (5-FU and Mitomycin)", "Amputation", "None"]', 1, 'Surgery is reserved for salvage. (Mont Reid Ch. 8)'),
    (v_topic_id, '60: "Fecal Incontinence" - initial treatment?', '["Surgery", "Fiber, bowel training, and anti-diarrheals", "Colostomy", "None"]', 1, 'Medical management first. (Schwartz''s Ch. 31)'),
    (v_topic_id, '61: "SMA" - supplies? ', '["Duodenum to Mid-transverse colon", "Stomach", "Rectum", "None"]', 0, 'Foregut/Midgut boundary. (de Virgilio Ch. 21)'),
    (v_topic_id, '62: "IMA" - supplies? ', '["Mid-transverse to Rectum", "Jejunum", "Stomach", "None"]', 0, 'Hindgut. (Mont Reid Ch. 8)'),
    (v_topic_id, '63: "Superior Rectal Artery" is a branch of the ____.', '["Internal Iliac", "IMA", "Aorta", "None"]', 1, 'Main supply to the rectum. (Schwartz''s Ch. 29)'),
    (v_topic_id, '64: "Middle Rectal Artery" is a branch of the ____.', '["IMA", "Internal Iliac", "External Iliac", "None"]', 1, 'Lateral supply. (de Virgilio Ch. 16)'),
    (v_topic_id, '65: "Inferior Rectal Artery" is a branch of the ____.', '["IMA", "Internal Pudendal Artery", "Aorta", "None"]', 1, 'Supplies the lower anal canal. (Mont Reid Ch. 8)'),
    (v_topic_id, '66: "Appendiceal Carcinoid" < 1 cm: Treatment?', '["Right hemicolectomy", "Appendectomy alone", "Chemo", "None"]', 1, 'If > 2 cm, do a right hemicolectomy. (Schwartz''s Ch. 30)'),
    (v_topic_id, '67: "Mucinous Cystadenoma" of the appendix: Risk?', '["None", "Pseudomyxoma Peritonei if it ruptures", "SBO", "None"]', 1, '"Jelly belly." (de Virgilio Ch. 13)'),
    (v_topic_id, '68: "Diverticular Bleed": Most common side?', '["Left (Sigmoid)", "Right (Cecum/Ascending)", "Both", "None"]', 1, 'Even though diverticulitis is more common on the left. (Mont Reid Ch. 8)'),
    (v_topic_id, '69: "Angiodysplasia" of the colon: Most common location?', '["Sigmoid", "Cecum / Right colon", "Rectum", "None"]', 1, 'Associated with Heyde Syndrome (Aortic Stenosis). (Schwartz''s Ch. 29)'),
    (v_topic_id, '70: "Heyde Syndrome" triad: Aortic Stenosis, Angiodysplasia, and ____.', '["Fever", "Acquired von Willebrand deficiency", "Stroke", "None"]', 1, 'Leads to GI bleeding. (de Virgilio Ch. 13)'),
    (v_topic_id, '71: "Peutz-Jeghers Syndrome": Signs?', '["Hamartomatous polyps + Perioral pigmentation", "FAP", "None", "None"]', 0, 'STK11 mutation. (Mont Reid Ch. 8)'),
    (v_topic_id, '72: "Gardner Syndrome": Triad?', '["FAP + Osteomas + Soft tissue tumors/desmoids", "None", "Both", "None"]', 2, 'Variant of FAP. (Schwartz''s Ch. 29)'),
    (v_topic_id, '73: "Turcot Syndrome": Association?', '["FAP + CNS tumors (Medulloblastoma/Glioma)", "None", "Both", "None"]', 2, 'Rare but high-yield. (de Virgilio Ch. 16)'),
    (v_topic_id, '74: "Colorectal Cancer" - most common site of metastasis?', '["Lung", "Liver", "Bone", "Brain"]', 1, 'Due to portal venous drainage. (Mont Reid Ch. 8)'),
    (v_topic_id, '75: "Rectal Cancer" - metastasis? ', '["Lower rectum can drain to the IVC (via inferior rectal veins) and metastasize to lungs first", "Always liver", "None", "None"]', 0, 'Important for staging. (Schwartz''s Ch. 29)'),
    (v_topic_id, '76: "Ileus" vs "Obstruction": Ileus has ____ bowel sounds.', '["High pitched", "Absent or Hypoactive", "Metallic", "None"]', 1, 'Failure of motility. (de Virgilio Ch. 21)'),
    (v_topic_id, '77: "Pseudo-obstruction" - X-ray? ', '["Dilated colon up to the splenic flexure or rectum without a mass", "Air-fluid", "None", "None"]', 0, 'Ogilvie. (Mont Reid Ch. 8)'),
    (v_topic_id, '78: "Crohn''s" - Smoking? ', '["Protective", "Risk factor (worsens disease)", "No effect", "None"]', 1, 'Contrast with UC. (Schwartz''s Ch. 28)'),
    (v_topic_id, '79: "Ulcerative Colitis" - Smoking? ', '["Risk factor", "Protective (quitting can flare disease)", "None", "None"]', 1, 'Odd but consistent finding. (de Virgilio Ch. 15)'),
    (v_topic_id, '80: "Short Bowel Syndrome" occurs when < ____ cm of small bowel remains.', '["50", "200", "500", "None"]', 1, 'Leads to malabsorption/dehydration. (Mont Reid Ch. 8)'),
    (v_topic_id, '81: "Anorectal Abscess" - Ischiorectal? ', '["Large, presents with deep pain", "Lateral to sphincters", "Both", "None"]', 2, 'Needs wide drainage. (Schwartz''s Ch. 31)'),
    (v_topic_id, '82: "Anorectal Abscess" - Intersphincteric? ', '["Most common type", "Between muscles", "Both", "None"]', 2, 'Difficult to see on surface. (de Virgilio Ch. 16)'),
    (v_topic_id, '83: "Anal Fissure" - Sentinal pile? ', '["Skin tag at the distal end of a chronic fissure", "Cancer", "None", "None"]', 0, 'Sign of chronicity. (Mont Reid Ch. 8)'),
    (v_topic_id, '84: "Rectovaginal Fistula" - Crohn''s? ', '["Common cause", "Difficult to repair", "Both", "None"]', 2, 'Surgical challenge. (Schwartz''s Ch. 28)'),
    (v_topic_id, '85: "Pruritus Ani": Most common cause?', '["Infection", "Poor hygiene or Over-cleaning", "Cancer", "None"]', 1, 'Dermatologic issue. (de Virgilio Ch. 16)'),
    (v_topic_id, '86: "Condyloma Acuminata" (Anal Warts) are caused by:', '["HIV", "HPV (Types 6, 11)", "HSV", "None"]', 1, 'Increased risk of anal cancer (HPV 16, 18). (Mont Reid Ch. 8)'),
    (v_topic_id, '87: "Rectal Prolapse" - Children? ', '["Associated with Cystic Fibrosis", "Normal", "None", "None"]', 0, 'Due to chronic constipation/straining. (Schwartz''s Ch. 29)'),
    (v_topic_id, '88: "Colonic Stents": Use?', '["Curative for cancer", "Palliative or bridge to surgery in obstruction", "None", "None"]', 1, 'Avoids emergent stoma. (de Virgilio Ch. 16)'),
    (v_topic_id, '89: "J-Pouch" - what is it made of?', '["Colon", "Terminal Ileum", "Jejunum", "None"]', 1, 'Functions as a neo-rectum. (Mont Reid Ch. 8)'),
    (v_topic_id, '90: "Pouchitis" is treated with:', '["Surgery", "Antibiotics (Metronidazole / Ciprofloxacin)", "Steroids", "None"]', 1, 'Inflammation of the J-pouch. (Schwartz''s Ch. 29)'),
    (v_topic_id, '91: "Mesenteric vein thrombosis": Risk factor?', '["Atrial fibrillation", "Hypercoagulable states (Protein C/S deficiency)", "Smoking", "None"]', 1, 'Presents more subacutely than arterial embolism. (de Virgilio Ch. 22)'),
    (v_topic_id, '92: "Non-occlusive Mesenteric Ischemia" (NOMI) is caused by:', '["Clot", "Vasoconstriction (e.g., in low-flow states, shock, or pressors)", "Trauma", "None"]', 1, 'Treated with intra-arterial vasodilators (Papaverine). (Schwartz''s Ch. 23)'),
    (v_topic_id, '93: "Fecal Calprotectin": Use?', '["Detects cancer", "Markers for IBD inflammation", "Detects blood", "None"]', 1, 'Stool test. (Mont Reid Ch. 8)'),
    (v_topic_id, '94: "ASCA" vs "p-ANCA": Which is associated with Crohn''s?', '["ASCA", "p-ANCA", "Both", "None"]', 0, 'p-ANCA is more for UC. (de Virgilio Ch. 15)'),
    (v_topic_id, '95: "Rectal cancer" - Neoadjuvant Therapy? ', '["Required for T3/T4 or N+ disease (Chemo-radiation)", "Surgery first", "None", "None"]', 0, 'Shrinks tumor and improves sphincter preservation. (Schwartz''s Ch. 29)'),
    (v_topic_id, '96: "T1" CRC involves ____; "T3" involves ____.', '["Mucosa; Submucosa", "Submucosa; Through muscularis into subserosa", "Muscle; Bone", "None"]', 1, 'Staging. (Mont Reid Ch. 8)'),
    (v_topic_id, '97: "Colonoscopy" - perforation rate?', '["1 in 10", "1 in 1000", "1 in 100,000", "None"]', 1, 'Low but significant risk. (de Virgilio Ch. 16)'),
    (v_topic_id, '98: "Diverticular bleed" - angiography requires rate of ____ mL/min.', '["0.1", "0.5 to 1.0", "5.0", "None"]', 1, 'Needed to see extravasation. (Schwartz''s Ch. 29)'),
    (v_topic_id, '99: "Barium Enema" - classic finding in UC?', '["Lead pipe", "Bird beak", "Apple core", "None"]', 0, 'Loss of haustration. (Mont Reid Ch. 8)'),
    (v_topic_id, '100: "Barium Enema" - classic finding in Colon Cancer?', '["Lead pipe", "Apple core", "Thumbprinting", "None"]', 1, 'Circumferential narrowing. (de Virgilio Ch. 16)');

    -- Batch 3: 101-350 (Rapid Fire and Special Cases)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
